import ReconnectingWebSocket from "partysocket/ws";
import type {
  ConnectionEvent,
  ConnectionTransportCallback,
  IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops silently; the transport rewrites the close reason to
// TRANSPORT_EXHAUSTED_REASON so callers can detect the give-up.
export const MAX_RETRIES = 10;

// Sentinel close reason written by the transport once the retry budget is
// exhausted. Recognized by `classifyCloseEvent` as the "gave-up" signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

/**
 * Build a close event that mirrors `event` but carries a rewritten reason.
 *
 * Falls back to a plain object when `CloseEvent` cannot be constructed in the
 * current environment.
 */
function rewriteCloseReason(event: CloseEvent, reason: string): CloseEvent {
  try {
    return new CloseEvent("close", {
      code: event.code,
      reason,
      wasClean: event.wasClean,
    });
  } catch {
    // Some environments don't allow constructing CloseEvent; return a
    // structurally-compatible object with the rewritten reason.
    return {
      type: "close",
      code: event.code,
      reason,
      wasClean: event.wasClean,
    } as unknown as CloseEvent;
  }
}

/**
 * A WebSocket transport that wraps a reconnecting WebSocket and intercepts
 * close events.
 *
 * When the inner socket's retry budget ({@link MAX_RETRIES}) is exhausted, the
 * transport rewrites the close event's reason to
 * {@link TRANSPORT_EXHAUSTED_REASON} before forwarding it to listeners — even
 * when the original close event carried a server-sent reason. While retries
 * remain, close events are forwarded unchanged.
 */
export class WsTransport implements IConnectionTransport {
  private readonly inner: ReconnectingWebSocket;

  // For each event, maps a registered callback to the wrapper actually
  // attached to the inner socket. Keyed by callback reference so repeated
  // registrations of the same callback are deduplicated, and a single
  // removal fully unregisters it.
  private readonly wrappers = new Map<
    ConnectionEvent,
    Map<
      ConnectionTransportCallback<ConnectionEvent>,
      (event: unknown) => void
    >
  >();

  constructor(urlFactory: () => string) {
    // We don't call the URL provider now since it may change (i.e. if the
    // runtime redirects).
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const typedCallback = callback as ConnectionTransportCallback<ConnectionEvent>;
    let byCallback = this.wrappers.get(event);
    if (!byCallback) {
      byCallback = new Map();
      this.wrappers.set(event, byCallback);
    }
    // Deduplicate: registering the same callback more than once must not cause
    // it to fire multiple times.
    if (byCallback.has(typedCallback)) {
      return;
    }

    const wrapper =
      event === "close"
        ? (e: unknown) =>
            typedCallback(this.maybeRewriteClose(e as CloseEvent) as never)
        : (e: unknown) => typedCallback(e as never);

    byCallback.set(typedCallback, wrapper);
    this.inner.addEventListener(
      event as keyof WebSocketEventMap,
      wrapper as EventListener,
    );
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const typedCallback = callback as ConnectionTransportCallback<ConnectionEvent>;
    const byCallback = this.wrappers.get(event);
    const wrapper = byCallback?.get(typedCallback);
    if (!wrapper || !byCallback) {
      return;
    }
    // A single call fully unregisters the callback, removing the wrapper from
    // the underlying socket so no orphaned listeners remain.
    this.inner.removeEventListener(
      event as keyof WebSocketEventMap,
      wrapper as EventListener,
    );
    byCallback.delete(typedCallback);
  }

  private maybeRewriteClose(event: CloseEvent): CloseEvent {
    if (this.inner.retryCount >= MAX_RETRIES) {
      return rewriteCloseReason(event, TRANSPORT_EXHAUSTED_REASON);
    }
    return event;
  }
}
