import { describe, expect, it, vi } from "vitest";
import {
  MAX_RETRIES,
  TRANSPORT_EXHAUSTED_REASON,
  WsTransport,
} from "./ws";

class FakeInner {
  retryCount = 0;
  readyState = WebSocket.CLOSED;
  private listeners = new Map<string, Set<EventListener>>();
  addEventListener(type: string, cb: EventListener) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, new Set());
    }
    this.listeners.get(type)!.add(cb);
  }
  removeEventListener(type: string, cb: EventListener) {
    this.listeners.get(type)?.delete(cb);
  }
  countListeners(type: string) {
    return this.listeners.get(type)?.size ?? 0;
  }
  dispatch(type: string, event: unknown) {
    for (const cb of this.listeners.get(type) ?? []) {
      cb(event as Event);
    }
  }
  reconnect() {}
  close() {}
  send() {}
}

function make() {
  const t = new WsTransport(() => "ws://localhost/ws");
  const fake = new FakeInner();
  (t as unknown as { inner: FakeInner }).inner = fake;
  return { t, fake };
}

describe("WsTransport", () => {
  it("rewrites reason when exhausted (even with server reason)", () => {
    const { t, fake } = make();
    fake.retryCount = MAX_RETRIES;
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    fake.dispatch("close", { code: 1006, reason: "server-said-bye", wasClean: false });
    expect(cb).toHaveBeenCalledTimes(1);
    expect(cb.mock.calls[0][0].reason).toBe(TRANSPORT_EXHAUSTED_REASON);
  });

  it("forwards original reason when retries remain", () => {
    const { t, fake } = make();
    fake.retryCount = MAX_RETRIES - 1;
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    fake.dispatch("close", { code: 1006, reason: "keep-me", wasClean: false });
    expect(cb.mock.calls[0][0].reason).toBe("keep-me");
  });

  it("dedupes duplicate registrations", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    t.addEventListener("close", cb as never);
    expect(fake.countListeners("close")).toBe(1);
    fake.dispatch("close", { code: 1000, reason: "", wasClean: true });
    expect(cb).toHaveBeenCalledTimes(1);
  });

  it("single remove fully unregisters, no orphans", () => {
    const { t, fake } = make();
    const cb = vi.fn();
    t.addEventListener("close", cb as never);
    t.addEventListener("close", cb as never);
    t.removeEventListener("close", cb as never);
    expect(fake.countListeners("close")).toBe(0);
    fake.dispatch("close", { code: 1000, reason: "", wasClean: true });
    expect(cb).not.toHaveBeenCalled();
  });
});
