import { describe, expect, it, vi } from "vitest";
import { WebSocketClosedReason, WebSocketState } from "../websocket/types";
import { classifyCloseEvent } from "../websocket/useMarimoKernelConnection";
import { RuntimeManager } from "./runtime";
import type { RuntimeConfig } from "./types";

vi.mock("@/core/kernel/session", () => ({ getSessionId: () => "sid" }));

describe("classifyCloseEvent single-arg", () => {
  it("undefined reason -> retry", () => {
    expect(classifyCloseEvent({ reason: undefined }).kind).toBe("retry");
  });
  it("TRANSPORT_EXHAUSTED -> gave-up", () => {
    const d = classifyCloseEvent({ reason: "MARIMO_TRANSPORT_EXHAUSTED" });
    expect(d).toEqual({
      kind: "gave-up",
      status: {
        state: WebSocketState.CLOSED,
        code: WebSocketClosedReason.KERNEL_DISCONNECTED,
        reason: "kernel not found",
      },
    });
  });
});

const cfg: RuntimeConfig = { url: "https://backend.example.com/lazy?some_value=abc123", lazy: true };

describe("probeHealth vs reconcileFromHealth", () => {
  it("probeHealth returns bools and does NOT mutate url on redirect", async () => {
    const rt = new RuntimeManager(cfg, true);
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health?some_value=abc123",
    });
    expect(await rt.probeHealth()).toBe(true);
    expect(rt.httpURL.hostname).toBe("backend.example.com");

    global.fetch = vi.fn().mockResolvedValue({ ok: false });
    expect(await rt.probeHealth()).toBe(false);
    global.fetch = vi.fn().mockRejectedValue(new Error("net"));
    expect(await rt.probeHealth()).toBe(false);
  });

  it("reconcileFromHealth mutates url on redirect", async () => {
    const rt = new RuntimeManager({ ...cfg }, true);
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      redirected: true,
      url: "https://sandbox.example.com/health?some_value=abc123",
    });
    expect(await rt.reconcileFromHealth()).toBe(true);
    expect(rt.httpURL.hostname).toBe("sandbox.example.com");
    expect(rt.httpURL.searchParams.get("some_value")).toBe("abc123");
    document.querySelectorAll("base").forEach((el) => el.remove());
  });

  it("formatHttpURL object arg", () => {
    const rt = new RuntimeManager({ url: "https://example.com", lazy: true }, true);
    const u = rt.formatHttpURL({
      path: "api/test",
      searchParams: new URLSearchParams(),
      restrictToKnownQueryParams: false,
    });
    expect(u.pathname).toBe("/api/test");
  });
});
